// Parse Telegram /commands and prepare WF-D dispatch
// Output: { needsWFD, op, payload, replyText, chatId, titleForReply, command }

const item = $input.first().json;
const message = item.message || {};
const text = (message.text || '').trim();
const chatId = message.chat?.id;
const userName = message.from?.first_name || 'friend';

const [cmdRaw, ...argParts] = text.split(/\s+/);
const command = (cmdRaw || '').replace(/@\w+$/, '').toLowerCase();
const args = argParts.join(' ').trim();

const UUID_RE = /([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/i;
const TITLE_RE = /mangadex\.org\/title\/([0-9a-f-]{36})/i;
const CHAPTER_RE = /mangadex\.org\/chapter\/([0-9a-f-]{36})/i;

let result = { needsWFD: false, chatId, replyText: '', op: null, payload: {}, command, titleForReply: '' };

try {
  switch (command) {
    case '/start':
    case '/help': {
      result.replyText = [
        `Hi ${userName}! I manage manga sources for the auto-poster.`,
        ``,
        `*Commands:*`,
        '`/add <mangadex-title-or-chapter-url-or-id>` - track a manga',
        '`/list` - show sources, queue, recent posts',
        '`/remove <mangadex-id>` - stop tracking',
        '`/help` - this message',
        ``,
        `Sources are auto-checked by the scheduler.`
      ].join('\n');
      break;
    }
    case '/add': {
      if (!args) {
        result.replyText = 'Usage: `/add <mangadex-title-or-chapter-url-or-id>`';
        break;
      }

      const titleMatch = args.match(TITLE_RE);
      const chapterMatch = args.match(CHAPTER_RE);
      const rawUuid = args.match(UUID_RE);

      result.needsWFD = true;
      result.op = 'addSource';

      if (titleMatch) {
        const mangaId = titleMatch[1].toLowerCase();
        result.payload = { type: 'mangadex', mangaId, title: '' };
        result.titleForReply = mangaId;
      } else if (chapterMatch) {
        const chapterId = chapterMatch[1].toLowerCase();
        result.payload = { type: 'mangadex', chapterId, title: '' };
        result.titleForReply = chapterId;
      } else if (rawUuid) {
        const mangaId = rawUuid[1].toLowerCase();
        result.payload = { type: 'mangadex', mangaId, title: '' };
        result.titleForReply = mangaId;
      } else {
        result.needsWFD = false;
        result.replyText = 'Could not parse a MangaDex title/chapter UUID.';
      }
      break;
    }
    case '/list': {
      result.needsWFD = true;
      result.op = 'list';
      result.payload = {};
      break;
    }
    case '/remove': {
      if (!args) { result.replyText = 'Usage: `/remove <mangadex-id>`'; break; }
      const mangaId = (args.match(UUID_RE)?.[1] || '').toLowerCase();
      if (!mangaId) { result.replyText = 'Could not parse a MangaDex UUID.'; break; }
      result.needsWFD = true;
      result.op = 'removeSource';
      result.payload = { mangaId };
      break;
    }
    default:
      result.replyText = 'Unknown command. Try `/help`.';
  }
} catch (err) {
  result.needsWFD = false;
  result.replyText = `Error: ${err.message || String(err)}`;
}

return [{ json: result }];

// Format WF-D response into Telegram reply
const wfd = $input.first().json;
const orig = $('Parse + Validate').first().json;
const op = orig.op;

let replyText = '';

if (op === 'addSource') {
  if (wfd.ok) {
    replyText = `✅ Added source: *${orig.titleForReply}*\nTotal sources: ${wfd.totalSources}`;
  } else if (wfd.error === 'source already exists') {
    replyText = `ℹ️ Already tracking *${wfd.source?.title || orig.titleForReply}*.`;
  } else {
    replyText = `❌ ${wfd.error || 'unknown error'}`;
  }
} else if (op === 'list') {
  if (wfd.ok) {
    const c = wfd.counts;
    const sources = (wfd.sources || []).map(s => `• *${s.title || s.mangaId}* (\`${s.mangaId.slice(0,8)}...\`)`).join('\n') || '_(none)_';
    replyText = [
      `\u{1F4DA} *Status*`,
      ``,
      `*Sources* (${c.sources}):`,
      sources,
      ``,
      `*Queue:* ${c.queue} chapters waiting`,
      `*Posted:* ${c.posted} total`
    ].join('\n');
  } else {
    replyText = `❌ ${wfd.error || 'unknown error'}`;
  }
} else if (op === 'removeSource') {
  replyText = wfd.ok && wfd.removed > 0 ? `\u{1F5D1}️ Removed source.` : `\u{1F937} No matching source found.`;
} else {
  replyText = '```\n' + JSON.stringify(wfd, null, 2) + '\n```';
}

return [{ json: { replyText, chatId: orig.chatId } }];

const base = $('Parse + Validate').first().json;
const chapterRes = $input.first().json;

const rels = chapterRes?.data?.relationships || [];
const mangaRel = rels.find(r => r.type === 'manga' && r.id);

if (!mangaRel?.id) {
  return [{
    json: {
      ...base,
      needsWFD: false,
      replyText: 'Could not resolve manga from chapter URL.'
    }
  }];
}

const mangaId = String(mangaRel.id).toLowerCase();

return [{
  json: {
    ...base,
    payload: {
      ...base.payload,
      mangaId,
      title: base.payload?.title || ''
    },
    titleForReply: mangaId
  }
}];

const base = $('Is addSource?').first().json;
const manga = $input.first().json;

const attrs = manga?.data?.attributes || {};
const titles = attrs.title || {};
const title = titles.en || titles['ja-ro'] || titles.ja || Object.values(titles)[0] || base.payload?.mangaId || '(untitled)';

return [{
  json: {
    ...base,
    payload: {
      ...base.payload,
      title
    },
    titleForReply: title
  }
}];

const feed = $input.first().json;
const wfd = $('Call WF-D').first().json;
const chapters = feed.data || [];
const pick = chapters.find(c => c.attributes && c.attributes.pages > 0);
if (!pick) return [];
const chapterNum = parseFloat(pick.attributes.chapter);
return [{ json: {
  mangaId: wfd.source.mangaId,
  chapterId: pick.id,
  title: wfd.source.title || wfd.source.mangaId,
  chapterNum: isNaN(chapterNum) ? null : chapterNum
}}];
